#!/usr/bin/env python3
"""
Round 151b (culprits), 4 October 2026. Needs round 150b.

Redoes the woodlands basemap in soft tones.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 151b (4 October)\n\nNeeds round 150b. No tiles patch. No app.js?v= bump. Woodlands basemap redone.\n\n- The 150b basemap (Autumn woodlands) redone as Woodlands after the owner found\n  its leaf dabs a pattern. Asked: Robert Griffing's tonalist green woodlands,\n  not a pattern. Now one soft key: greyed sage and olive greens and warm\n  greys; ground paler, greyer and bluer with height (atmospheric perspective);\n  soft golden light from the south-west, gentle grey-green shadow; warm grey\n  mist in valleys and over water; still grey-green water; hazy sky.\n- woodbrush:// now paints smooth, blended clouds of darker and paler tone and\n  level mist from each pixel's place in the world (no marks, no seams; about\n  35 ms a square). Leaf dabs (woodMarks) gone. Greens and earth colours here\n  only, at the owner's request; all greyed (tested, saturation under 0.4).\n  Not seen against real tiles.\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round151b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 150b" not in h.read_text(encoding="utf-8"):
        sys.exit("round151b: round 150b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round151b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round151b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round151b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
